<template>
  <main class="bidding-workbench" v-loading="loading">
    <header class="page-heading"><div><el-button link type="primary" @click="router.push('/bidding')">← {{ l('项目列表','Projects') }}</el-button><h1>{{ project?.name || l('投标工作台','Bidding workbench') }}</h1></div><div class="heading-actions"><el-button v-if="project && capabilities?.canWrite" type="primary" @click="handoffOpen=true">{{ l('接收售前版本','Receive presales version') }}</el-button><el-button v-if="project" type="primary" plain @click="taskDrawer=true">{{ l('任务记录','Task records') }}</el-button><el-button v-if="canApproveProject" type="primary" plain @click="ownerDialog=true">{{ l('项目档案','Project settings') }}</el-button><el-button type="primary" plain @click="load">{{ l('刷新','Refresh') }}</el-button></div></header>
