        <el-tab-pane :label="l('文件与来源','Sources')" name="sources"><BiddingSources :project="project" :sources="sources" :source-set="sourceSet" :loading="sourcesLoading" :can-write="!!capabilities.canWrite" :can-approve="canApproveProject" :analyst-ready="analystReady" :active-analysis="activeAnalysis" :dispatching="dispatching" @changed="refreshSources" @preview="preview" @tasks="taskDrawer=true" @dispatch="dispatchAnalysis" @retry-read="retrySource" /><BiddingMaterials :workspace-id="workspace.currentWorkspaceId || ''" :project="project" :items="materials" :loading="materialsLoading" :can-write="!!capabilities.canWrite" :busy="p2Busy" :error="materialsError" @bind="bindMaterial" @changed="refreshMaterials" /></el-tab-pane>
