        <el-tab-pane :label="l('目录规划','Outline')" name="outline"><BiddingOutline ref="outlineSurface" :view="outline" :project-ref="project.ref" :saved-ref="outlineSavedRef" :clear-token="outlineClearToken" :can-write="!!capabilities.canWrite" :can-approve="canApproveProject" :can-dispatch="canDispatchOutline" :busy="p2Busy" :dispatching="outlineDispatching" :saving="outlineSaving" :confirming="outlineConfirming" :error="outlineError" @command="outlineCommand" /></el-tab-pane>
        <el-tab-pane :label="l('技术标写作','Writing')" name="writing"><BiddingWriting ref="writingSurface" :view="writing" :can-write="!!capabilities.canWrite" :can-dispatch="!!outline.confirmed && !!capabilities.canWrite" :busy="p2Busy" :dispatching-chapter-ids="dispatchingChapterIds" :error="writingError" :saved-token="writingSavedToken" :clear-token="writingClearToken" @dispatch="dispatchWriting" @command="writingCommand" @retry-task="retryWritingTask" @assemble="assembleManuscript" /></el-tab-pane>
        <el-tab-pane :label="l('审核与导出','Review')" name="review"><div class="review-export-layout"><BiddingReview :view="reviewView" :chapters="writing.chapters.map(item=>({id:item.chapterId,title:item.title}))" :can-write="!!capabilities.canWrite" :can-approve="canApproveProject" :can-resolve-todo="canApproveProject" :reviewer-ready="reviewerReady" :busy="reviewBusy" @refresh="refreshReviewAndArtifacts" @dispatch="dispatchReview" @fix="targetFinding" @resolve="openFindingDecision" @classify="openTodoClassification" @resolve-todo="openTodoResolution" @evidence="openEvidence" @chapter="focusChapter"/><BiddingArtifacts :templates="templates" :artifacts="artifacts" :loading="artifactLoading" :busy="exportBusy" :can-write="!!capabilities.canWrite" :can-approve="canApproveProject" @refresh="refreshReviewAndArtifacts" @prepare="prepareExport" @generate="generateExport" @download="downloadArtifact" @approval-context="openApproval" /></div></el-tab-pane>
      </el-tabs>
    </template>
    <el-dialog v-model="ownerDialog" :title="l('项目档案','Project settings')" width="min(560px,94vw)" :close-on-click-modal="false">
      <el-form label-position="right" label-width="110px"><el-form-item :label="l('项目名称','Project name')"><el-input v-model="projectDraft.name" maxlength="200" /></el-form-item><el-form-item :label="l('标段','Lot')"><el-input v-model="projectDraft.lotName" maxlength="200" /></el-form-item><el-form-item :label="l('负责人','Owner')"><el-select v-model="projectDraft.ownerId" filterable :loading="membersLoading" :disabled="membersLoading || !members.length"><el-option v-for="member in members" :key="String(member.userId)" :label="memberLabel(member)" :value="String(member.userId)" /></el-select></el-form-item></el-form>
      <template #footer><el-button @click="ownerDialog=false">{{ l('取消','Cancel') }}</el-button><el-button type="primary" :loading="saving" :disabled="!projectDraft.name.trim()||!projectDraft.lotName.trim()" @click="saveProject">{{ l('保存','Save') }}</el-button></template>
    </el-dialog>
